5	/**
6	 * Business rule: on creation an owner is assigned a numeric {@code membershipLevel} from 1 to 3.
7	 * It starts at 1, gains 1 when an email is present, gains 1 when {@code namesakeCount} is 0, and is
8	 * capped at 3 (level 4 is reserved for tenure). Kept as a small, self-contained unit so the rule can
9	 * be applied from the read and audit flows without adding complexity to the mapper, controller, or
10	 * service.
11	 */
12	public final class OwnerMembershipLevelPolicy {
13	
14	    private static final int MAX_LEVEL = 3;
15	
16	    private OwnerMembershipLevelPolicy() {
17	    }
18	
19	    /**
20	     * Derive the {@code membershipLevel} for the given owner.
21	     *
22	     * @param owner the owner whose membership level to derive
23	     * @return the level, from 1 to 3
24	     */
25	    public static int membershipLevel(Owner owner) {
26	        int level = 1;
27	        String email = owner.getEmail();
28	        if (email != null && !email.isEmpty()) {
29	            level++;
30	        }
31	        Integer namesakeCount = owner.getNamesakeCount();
32	        if (namesakeCount != null && namesakeCount == 0) {
33	            level++;
34	        }
35	        return Math.min(level, MAX_LEVEL);
36	    }
37	}
